{%- set company = frappe.get_doc("Company", doc.company) -%}

<!-- --- MERGE DATA: RAW MATERIALS (PRIORITIZE STOCK ENTRY) --- -->
{%- set actual_transfers = {} -%}
{# Fetch Stock Entries of type 'Send to Subcontractor' that link back to this SO #}
{%- set se_list = frappe.db.get_list(
    "Stock Entry", 
    {"stock_entry_type": "Send to Subcontractor", "subcontracting_order": doc.name}, 
    ["name"]
) -%}

{%- for se_doc in se_list -%}
    {%- set se = frappe.get_doc("Stock Entry", se_doc.name) -%}

    {%- for entry in se.items -%}
        {# **IMPORTANT:** For "Send to Subcontractor", raw materials sent OUT are often in the 'Stock Out' part of the SE. 
           We look for a specific purpose or check if the transfer is in the expected direction/warehouse based on setup.
           Since you only need what was sent out, we simplify to check all items in the filtered SEs. 
           You might need to check entry.is_return/entry.is_stock_out or warehouse names for tighter control if this includes more than just raw material issue. #}

        {%- if entry.item_code and entry.qty > 0 -%}  {# Only consider items with a code and a positive quantity in this SE row #}

            {%- set item_code = entry.item_code -%}
            {%- set qty_transferred = entry.qty -%}

            {%- if item_code in actual_transfers -%}
                {%- set current_qty = actual_transfers[item_code].qty + qty_transferred -%}
                {%- set _ = actual_transfers[item_code].update({'qty': current_qty}) -%}
            {%- else -%}
                {%- set item_master = frappe.db.get_value("Item", item_code, ["item_name", "description", "stock_uom"], as_dict=1) or {} -%}
                {%- set new_entry = {
                    'item_code': item_code,
                    'item_name': item_master.item_name or item_code,
                    'description': item_master.description or "",
                    'uom': entry.stock_uom or "Nos", 
                    'qty': qty_transferred
                } -%}
                {%- set _ = actual_transfers.update({item_code: new_entry}) -%}
            {%- endif -%}
        {%- endif -%}
    {%- endfor -%}
{%- endfor -%}

{# --- Decide which list to use for printing (Final Items List for the main table) --- #}
{%- if actual_transfers -%}
    {# Priority 1: Use the aggregated quantity from linked Stock Entries #}
    {%- set final_items_list = actual_transfers.values() | list -%}
{%- else -%}
    {# Priority 2: Fallback to required items from the Subcontracting Order itself #}
    {%- set merged_items = {} -%}
    {%- for item in doc.supplied_items -%}
        {%- set item_code = item.rm_item_code -%}
        {%- if item_code in merged_items -%}
            {%- set current_qty = merged_items[item_code].qty + item.required_qty -%}
            {%- set _ = merged_items[item_code].update({'qty': current_qty}) -%}
        {%- else -%}
            {%- set item_master = frappe.db.get_value("Item", item_code, ["item_name", "description", "stock_uom"], as_dict=1) or {} -%}
            {%- set new_entry = {
                'item_code': item_code,
                'item_name': item_master.item_name or item_code,
                'description': item_master.description or "",
                'uom': item_master.stock_uom or "Nos",
                'qty': item.required_qty
            } -%}
            {%- set _ = merged_items.update({item_code: new_entry}) -%}
        {%- endif -%}
    {%- endfor -%}
    {%- set final_items_list = merged_items.values() | list -%}
{%- endif -%}

{%- set merged_fg_items = {} -%}
{%- for item in doc.items -%}
    {%- set fg_code = item.item_code -%}
    {%- if fg_code in merged_fg_items -%}
        {%- set current_qty = merged_fg_items[fg_code].qty + item.qty -%}
        {%- set _ = merged_fg_items[fg_code].update({'qty': current_qty}) -%}
    {%- else -%}
        {%- set fg_entry = {
            'item_code': fg_code,
            'item_name': item.item_name,
            'uom': item.stock_uom or "Nos", 
            'qty': item.qty
        } -%}
        {%- set _ = merged_fg_items.update({fg_code: fg_entry}) -%}
    {%- endif -%}
{%- endfor -%}
{%- set final_fg_list = merged_fg_items.values() | list -%}

<!-- --- ADDRESS LOGIC --- -->
{%- set supplier_line_1 = "M/s. " + doc.supplier_name -%}
{%- set supplier_line_2 = "" -%}
{%- if doc.address_display -%}
    {%- set addr_text = doc.address_display -%}
{%- elif doc.supplier_address -%}
    {%- set addr_doc = frappe.get_doc("Address", doc.supplier_address) -%}
    {%- set addr_text = addr_doc.display -%}
{%- endif -%}
{%- if addr_text -%}
    {%- set supplier_line_1 = supplier_line_1 + ", " + (addr_text | replace("\n", ", ") | replace("<br>", ", ")) -%}
{%- endif -%}
{%- if doc.contact_person -%}
    {%- set c = frappe.db.get_value("Contact", doc.contact_person, ["mobile_no", "email_id"], as_dict=1) -%}
    {%- if c -%}
        {%- if c.mobile_no %}{% set supplier_line_2 = supplier_line_2 + "Ph: " + c.mobile_no %}{% endif %}
    {%- endif -%}
{%- endif -%}

<!-- --- CHUNKING LOGIC --- -->
<!-- Using a large chunk size to force single page behavior unless massive data -->
{% set chunk_size = 18 %} 
{% set total_items = final_items_list|length %}
{% set chunks = (total_items // chunk_size) + (1 if total_items % chunk_size else 0) %}
{% if chunks == 0 %}{% set chunks = 1 %}{% endif %}

<style>
    @page { 
        margin: 3mm; /* Very small page margin */
        size: A4; 
    }

    body {
        font-family: Arial, sans-serif;
        font-size: 11pt;
        color: #000;
        margin: 0; padding: 0;
    }

    b, strong, th { font-weight: normal !important; }

    /* Main Frame */
 .wrapper {
    border: 2px solid #000;
    display: flex;
    flex-direction: column;
    min-height: 100%;
    width: 100%;
}




    /* Table Utils */
    table { width: 100%; border-collapse: collapse; border-spacing: 0; }
    td, th { padding: 4px; vertical-align: middle; }

    /* TITLE */
    .title-row {
        text-align: center;
        border-bottom: 2px solid #000;
        font-weight: bold;
        font-size: 13pt;
        padding: 5px;
    }

    /* HEADER */
    .header-tbl td { border: 1px solid #000; border-top: none; }

    .meta-row { display: flex; border-bottom: 1px solid #000; height: 23px; }
    .meta-row:last-child { border-bottom: none; }
    .m-lbl { width: 38%; border-right: 1px solid #000; padding: 2px 5px; font-size: 11pt; }
    .m-val { width: 62%; padding: 2px 5px; font-size: 11pt; }

    /* SUPPLIER */
    .supplier-box {
        padding: 6px;
        border-bottom: 2px solid #000; 
    }

    /* MAIN ISSUE ITEM TABLE */
    .issue-tbl th {
        border-bottom: 1px solid #000;
        border-right: 1px solid #000;
        text-align: center;
        font-weight: bold !important;
        background-color: white;
    }
    .issue-tbl th:last-child { border-right: none; }

    .issue-tbl td {
        border-right: 1px solid #000;
        border-bottom: 1px dotted #000; /* Data rows have dotted separation */
        vertical-align: top;
        padding: 6px 4px;
    }
    .issue-tbl td:last-child { border-right: none; }

    /* Ensure last row of data closes perfectly with a solid line via the container div or explicit rule */
    .last-row td { border-bottom: 1px solid #000 !important; }

    /* TOTAL ISSUED ROW */
    .total-issued {
        border-bottom: 2px solid #000; 
        text-align: right; 
        padding: 6px;
    }

    /* SPACER (The "White Space") */
    /* Pushes content down. Sides have borders from .wrapper. Center is blank. */
    .spacer {
        flex-grow: 1;
        width: 100%;
        background-color: #fff;
    }

    /* RECEIVED TABLE */
    .rec-header {
        border-top: 2px solid #000;
        padding: 5px;
        font-weight: bold;
        border-bottom: 1px solid #000;
    }

    .recv-tbl td, .recv-tbl th {
        border: 1px solid #000;
    }

    /* Remove outer borders of this table to merge with wrapper */
    .recv-tbl th:first-child, .recv-tbl td:first-child { border-left: none; }
    .recv-tbl th:last-child, .recv-tbl td:last-child { border-right: none; }

    /* Recv Table rows - fixed height for writing */
    .recv-tbl td { height: 26px; }

    /* FOOTER */
    .remarks {
        border-top: 2px solid #000;
        display: flex;
        border-bottom: 2px solid #000;
    }

    .sign-area {
        /* margin-top: auto; <- This is no longer needed with the new structure */
        padding: 50px 10px 10px 10px;
        display: flex;
        justify-content: space-between;
        text-align: center;
    }

    .sign-line { border-top: 1px solid #000; width: 80%; margin: 0 auto 5px auto; }
    .page-break { page-break-before: always; }

</style>

{% for page in range(chunks) %}
<div class="wrapper">

    <!-- 1. DOC TITLE -->
    <div class="title-row">GOODS ISSUE NOTE</div>

    <!-- 2. HEADER -->
    <table class="header-tbl" style="border: none;">
        <tr>
            <!-- LOGO -->
<td style="width: 20%; border-left: none; text-align: center; vertical-align: top;">
                 <img src="/files/Dacs inc Logo.jpeg" style="max-height: 100px; max-width: 100%;">
            </td>
            <!-- COMPANY INFO -->
<td style="width: 45%; text-align: center; vertical-align: top;">
                <div style="font-size: 14pt; text-transform: uppercase;">{{ company.name }}</div>
                <div style="font-size: 9pt; margin-top: 5px;">
                    Jaya Sai Towers No.40, 1st & 2nd floor, Sajjan Rao Road,<br>
                    Parvathipuram, V.V.Puram, Bangalore - 560004<br>
                    Ph: 080-41234140 | Email: accounts@dacsinc.in
                </div>
            </td>
            <!-- META DATA -->
<td style="width: 35%; padding: 0; border-right: none; vertical-align: top;">
                <div class="meta-row"><div class="m-lbl">Job Work No</div><div class="m-val">{{ doc.name }}</div></div>
                <div class="meta-row"><div class="m-lbl">Date</div><div class="m-val">{{ frappe.utils.formatdate(doc.transaction_date, "dd-MMM-yyyy") }}</div></div>
                <div class="meta-row"><div class="m-lbl">Transport</div><div class="m-val">&nbsp;</div></div>
                <div class="meta-row"><div class="m-lbl">Deli. Date</div><div class="m-val">{{ frappe.utils.formatdate(doc.schedule_date, "dd-MMM-yyyy") if doc.schedule_date else "-" }}</div></div>
            </td>
        </tr>
    </table>

    <!-- 3. SUPPLIER -->
    <div class="supplier-box">
        <div style="font-weight: bold;">{{ supplier_line_1 }}</div>
        {% if supplier_line_2 %}<div style="margin-top: 3px;">{{ supplier_line_2 }}</div>{% endif %}
    </div>

    <!-- 4. ITEMS TABLE (Issue) -->
    <table class="issue-tbl">
        <thead>
            <tr>
                <th style="width: 6%; text-align: center;">Sn.</th>
                <th style="width: 69%; text-align: left;">Issue Item Details</th>
                <th style="width: 10%; text-align: center;">UOM</th>
                <th style="width: 15%; text-align: center;">Qty</th>
            </tr>
        </thead>
        <tbody>
            {% set start = page * chunk_size %}
            {% set end = (page + 1) * chunk_size %}
            {% set items_on_page = final_items_list[start:end] %}

            {% for item in items_on_page %}
            <!-- Check if last item to add proper solid border at bottom -->
            <tr class="{{ 'last-row' if loop.last else '' }}">
                <td style="text-align: center;">{{ loop.index + start }}</td>
                <td>
                    <b>{{ item.item_code }}</b>
                    {% if item.description and item.description != item.item_name %}
                    <br><span style="font-size: 9pt; color: #555;">{{ item.description }}</span>
                    {% endif %}
                </td>
                <td style="text-align: center;">{{ item.uom }}</td>
                <td style="text-align: center;">{{ item.qty }}</td>
            </tr>
            {% endfor %}
            <!-- NO FILLER ROWS HERE, just white space below -->
        </tbody>
    </table>

    <!-- 5. TOTAL ISSUED QTY -->
    {% set ns = namespace(total_issued=0) %}
    {% for row in final_items_list %}{% set ns.total_issued = ns.total_issued + row.qty %}{% endfor %}
    <div class="total-issued">
        Total Issued Qty: <b>{{ ns.total_issued }}</b>
    </div>

    <!-- 6. FOOTER SECTION (On Last Page) -->
    {% if page + 1 == chunks %}
    <!-- This container will now fill the remaining space -->
    <div style="width: 100%; display: flex; flex-direction: column; flex-grow: 1;">

        <!-- Top part of the footer -->
        <div>
            <div class="rec-header">Receivable Product Summary</div>
            <table class="recv-tbl">
    <thead>
        <tr>
            <th style="width: 85%; text-align: left;">Item to be Received</th>
            <th style="width: 15%; text-align: center;">Qty</th>
        </tr>
    </thead>
    <tbody>
        <!-- Data Rows -->
        {% for item in final_fg_list %}
        <tr>
            <td>{{ item.item_code }}</td>
            <td style="text-align: center;">{{ item.qty }}</td>
        </tr>
        {% endfor %}

        <!-- Corrected Fixed Empty Rows (Now 2 columns to match header) -->
        {% for i in range(10) %}
        <tr>
            <td style="border-top: none; border-bottom: none;">&nbsp;</td>
            <td style="border-top: none; border-bottom: none;">&nbsp;</td>
        </tr>
        {% endfor %}
    </tbody>
</table>

            <!-- Totals & Remarks -->
            {% set fg_ns = namespace(total_fg=0) %}
            {% for row in final_fg_list %}{% set fg_ns.total_fg = fg_ns.total_fg + row.qty %}{% endfor %}

            <div class="remarks">
                <div style="width: 70%; padding: 6px; border-right: 1px solid #000; min-height: 40px;">
                    <b>Remarks:</b><br>
                    {{ doc.instructions or "" }}
                </div>
                <div style="width: 30%; display: flex; align-items: center; justify-content: center; font-size: 11pt;">
                    Total Qty: &nbsp;<b>{{ fg_ns.total_fg }}</b>
                </div>
            </div>
        </div>

        <!-- Internal spacer to push signatures to the bottom -->
        <!--<div style="flex-grow: 1;"></div>-->

        <!-- Bottom part of the footer (Signatures) -->
        <div>
            <!-- Signatures -->
           <div style="padding: 10px; text-align: center;">
            <!-- Top Row for the "For Company" text -->
            <div style="display: flex; justify-content: space-between; height: 100px;">
                <div style="width: 30%;"></div>
                <div style="width: 30%;"></div>
                <div style="width: 30%;">For <b>{{ company.name }}</b></div>
            </div>
            <!-- Bottom Row for the signature lines -->
            <div style="display: flex; justify-content: space-between;">
                <div style="width: 30%;">
                    <div class="sign-line"></div>
                    Receiver's Signature
                </div>
                <div style="width: 30%;">
                    <div class="sign-line"></div>
                    Checked By
                </div>
                <div style="width: 30%;">
                    <div class="sign-line"></div>
                    Authorised Signatory
                </div>
            </div>

            <div style="text-align: right; font-size: 8pt; color: #555; padding: 0 5px 2px 0; font-style: italic;">
                 Printed On: {{ frappe.utils.now() }}
            </div>
        </div>
    </div>
    {% else %}
      <!-- On pages that are not the last, use the original spacer -->
      <div class="spacer"></div>
    {% endif %}

</div>

{% if not loop.last %}
<div class="page-break"></div>
{% endif %}
{% endfor %}
